import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing, spring } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;800`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type CalendarZoomProps = Record<string, any>;

const CalendarZoom: React.FC<CalendarZoomProps> = ({
  backgroundColor = "#0A110D",
  transparentBackground = false,
  durationInSeconds = 8,
  cardBackgroundColor = "#13251A",
  primaryTextColor = "#E8F5E9",
  secondaryTextColor = "#81C784",
  accentColor = "#00E676",
  monthName = "March",
  targetDate = 27,
  zoomLevel = 4.5,
}) => {

  {/* Load Google Fonts */ }
  useFontLoader(["Outfit", "Playfair Display"]);
  {/* End Load Google Fonts */ }

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  const containerWidth = width * 0.65;
  const containerHeight = height * 0.85;

  // Animation Timings
  const introEnd = fps;
  const zoomStart = fps * 2;
  const zoomEnd = fps * 3.5;
  const circleStart = fps * 3.8;

  // Intro Animations
  const cardOpacity = interpolate(frame, [0, introEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic)
  });

  const cardY = interpolate(frame, [0, introEnd], [50, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.back(1.5))
  });

  // Zoom Animations
  const scale = interpolate(frame, [zoomStart, zoomEnd], [1, zoomLevel], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.inOut(Easing.cubic)
  });

  // Calendar Logic
  const daysInMonth = 31;
  const startDayOffset = 6; // E.g., March 2025 starts on a Saturday (index 6, where Sun=0)
  
  // Calculate Target Position for Zoom Origin
  // Grid is 8 rows by 7 columns
  // Row 0: Title, Row 1: Weekdays, Rows 2-7: Dates
  const targetIndex = startDayOffset + targetDate - 1;
  const targetCol = targetIndex % 7;
  const targetDateRow = Math.floor(targetIndex / 7);
  const targetGridRow = 2 + targetDateRow;

  const originX = ((targetCol + 0.5) / 7) * 100;
  const originY = ((targetGridRow + 0.5) / 8) * 100;

  // Calculate Pan to perfectly center the target date on screen
  const tx = containerWidth * (originX / 100);
  const ty = containerHeight * (originY / 100);

  const targetPanX = containerWidth / 2 - tx;
  const targetPanY = containerHeight / 2 - ty;

  const panX = interpolate(frame, [zoomStart, zoomEnd], [0, targetPanX], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.inOut(Easing.cubic)
  });

  const panY = interpolate(frame, [zoomStart, zoomEnd], [0, targetPanY], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.inOut(Easing.cubic)
  });

  // Circle Draw Animation
  const dashOffset = interpolate(frame, [circleStart, circleStart + fps * 0.8], [260, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic)
  });

  const circleOpacity = interpolate(frame, [circleStart, circleStart + 10], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const daysOfWeek = ["SUN", "MON", "TUE", "WED", "THU", "FRI", "SAT"];

  // Generate Array of Days
  const daysArray = Array.from({ length: 42 }, (_, i) => {
    if (i >= startDayOffset && i < startDayOffset + daysInMonth) {
      return i - startDayOffset + 1;
    }
    return null;
  });

  return (
    <AbsoluteFill style={{ 
      backgroundColor: bgColor, 
      fontFamily: "Outfit",
      display: "flex",
      justifyContent: "center",
      alignItems: "center",
      transition: "none"
    }}>
      
      {/* Container to handle exact scaling and origin */}
      <div style={{
        width: containerWidth,
        height: containerHeight,
        transformOrigin: `${originX}% ${originY}%`,
        transform: `translate(${panX}px, ${cardY + panY}px) scale(${scale})`,
        opacity: cardOpacity,
        backgroundColor: cardBackgroundColor,
        borderRadius: width * 0.02,
        boxShadow: `0 20px 50px rgba(0,0,0,0.4), inset 0 1px 0 rgba(255,255,255,0.1)`,
        display: "grid",
        gridTemplateColumns: "repeat(7, 1fr)",
        gridTemplateRows: "repeat(8, 1fr)",
        overflow: "hidden",
        border: `2px solid ${secondaryTextColor}20`,
        transition: "none"
      }}>

        {/* Header - Month Title */}
        <div style={{
          gridColumn: "1 / -1",
          display: "flex",
          justifyContent: "center",
          alignItems: "flex-end",
          paddingBottom: "2%",
          fontFamily: "Playfair Display",
          fontSize: width * 0.045,
          fontWeight: 700,
          color: primaryTextColor,
          letterSpacing: "0.05em",
          borderBottom: `1px solid ${secondaryTextColor}20`,
          transition: "none"
        }}>
          {monthName.toUpperCase()}
        </div>

        {/* Header - Days of Week */}
        {daysOfWeek.map((day, idx) => (
          <div key={`dow-${idx}`} style={{
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            fontSize: width * 0.012,
            fontWeight: 600,
            color: secondaryTextColor,
            letterSpacing: "0.1em",
            borderBottom: `1px solid ${secondaryTextColor}20`,
            transition: "none"
          }}>
            {day}
          </div>
        ))}

        {/* Calendar Grid */}
        {daysArray.map((dayNum, idx) => {
          const isTarget = dayNum === targetDate;
          
          return (
            <div key={`day-${idx}`} style={{
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              position: "relative",
              fontSize: width * 0.022,
              fontWeight: isTarget ? 700 : 400,
              color: dayNum ? primaryTextColor : "transparent",
              borderRight: (idx % 7 !== 6) ? `1px solid ${secondaryTextColor}10` : "none",
              borderBottom: (Math.floor(idx / 7) !== 5) ? `1px solid ${secondaryTextColor}10` : "none",
              transition: "none"
            }}>
              {/* Date Number */}
              <span style={{ 
                position: "relative", 
                zIndex: 2,
                opacity: dayNum ? 1 : 0,
                transition: "none"
              }}>
                {dayNum}
              </span>

              {/* Hand-drawn Circle for Target Date */}
              {isTarget && (
                <svg
                  viewBox="0 0 100 100"
                  style={{
                    position: "absolute",
                    top: "50%",
                    left: "50%",
                    width: "140%",
                    height: "140%",
                    transform: "translate(-50%, -50%)",
                    overflow: "visible",
                    zIndex: 1,
                    opacity: circleOpacity,
                    transition: "none",
                    filter: `drop-shadow(0px 0px 4px ${accentColor}80)`
                  }}
                >
                  <ellipse
                    cx="50"
                    cy="50"
                    rx="45"
                    ry="35"
                    fill="none"
                    stroke={accentColor}
                    strokeWidth="6"
                    strokeLinecap="round"
                    strokeDasharray={260}
                    strokeDashoffset={dashOffset}
                    style={{
                      transform: "rotate(-8deg)",
                      transformOrigin: "50% 50%",
                      transition: "none"
                    }}
                  />
                </svg>
              )}
            </div>
          );
        })}

      </div>
    </AbsoluteFill>
  );
};

export default CalendarZoom;